const ids = $input.all()
  .map(item => item.json['Message ID'])
  .filter(Boolean);

return [{ json: { existingIds: ids } }];

const config = $('Config').first().json;
const configLabels = (config.gmailLabels || '')
  .split(',')
  .map(l => l.trim())
  .filter(Boolean);

const existingIds = new Set(
  ($('Collect Existing IDs').first().json.existingIds || [])
);

const labelIdToName = new Map(
  $('Get Gmail Labels').all().map(item => [item.json.id, item.json.name])
);

const systemLabelPrefixes = ['CATEGORY_', 'UNREAD', 'IMPORTANT', 'STARRED', 'DRAFT', 'SENT', 'SPAM', 'TRASH', 'INBOX'];

function extractSender(json) {
  let name = '';
  let email = '';
  const from = json.from;

  if (from) {
    if (from.value && Array.isArray(from.value) && from.value.length) {
      name = from.value[0].name || '';
      email = from.value[0].address || '';
    } else if (Array.isArray(from) && from.length) {
      name = from[0].name || '';
      email = from[0].address || '';
    } else if (typeof from === 'object' && !Array.isArray(from)) {
      name = from.name || '';
      email = from.address || '';
    } else if (typeof from === 'string') {
      const match = from.match(/^(.*?)<([^>]+)>\s*$/);
      if (match) {
        name = match[1].trim().replace(/^"|"$/g, '');
        email = match[2].trim();
      } else {
        email = from.trim();
      }
    }
  }

  if (!email && typeof json.From === 'string') {
    const match = json.From.match(/^(.*?)<([^>]+)>\s*$/);
    if (match) {
      if (!name) name = match[1].trim().replace(/^"|"$/g, '');
      email = match[2].trim();
    } else if (!email) {
      email = json.From.trim();
    }
  }

  if (!name && email) name = email.split('@')[0];
  if (!name) name = 'Unknown Sender';

  return { name, email };
}

function sanitizeFolderName(name) {
  if (!name) return 'Unknown Sender';
  const cleaned = name.replace(/[\\/:*?"<>|]/g, '_').trim();
  return cleaned.length ? cleaned : 'Unknown Sender';
}

function resolveLabelNames(json) {
  if (Array.isArray(json.labelIds) && json.labelIds.length) {
    return json.labelIds.map(id => labelIdToName.get(id) || id);
  }
  if (Array.isArray(json.labels) && json.labels.length) {
    return json.labels.map(l => (l && (l.name || l.id)) || '').filter(Boolean);
  }
  return [];
}

function detectLabel(json) {
  const labelNames = resolveLabelNames(json);
  const match = labelNames.find(n => configLabels.some(cfg => cfg.toLowerCase() === String(n).toLowerCase()));
  if (match) {
    return configLabels.find(cfg => cfg.toLowerCase() === String(match).toLowerCase());
  }
  const custom = labelNames.find(n => !systemLabelPrefixes.some(p => String(n).toUpperCase().startsWith(p)));
  return custom || 'uncategorized';
}

function formatDate(json) {
  let d;
  if (json.internalDate) {
    const ts = Number(json.internalDate);
    if (!Number.isNaN(ts)) d = new Date(ts);
  }
  if (!d && json.Date) {
    const parsed = new Date(json.Date);
    if (!Number.isNaN(parsed.getTime())) d = parsed;
  }
  if (!d) d = new Date();
  return d.toISOString().slice(0, 10);
}

const results = [];
const inputItems = $input.all();

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const json = item.json;
  const messageId = json.id;

  if (!messageId || existingIds.has(messageId)) continue;

  const sender = extractSender(json);
  const label = detectLabel(json);
  const dateReceived = formatDate(json);
  const subject = json.Subject || json.subject || '(no subject)';

  // Dedupe attachments by filename + size
  const binary = item.binary || {};
  const seen = new Map();
  for (const key of Object.keys(binary)) {
    const b = binary[key];
    const fileName = b.fileName || key;
    const dedupeKey = fileName + ':' + (b.fileSize || '');
    if (!seen.has(dedupeKey)) {
      seen.set(dedupeKey, { key, fileName });
    }
  }

  const attachmentEntries = Array.from(seen.values());
  const hasAttachments = attachmentEntries.length > 0 ? 'Yes' : 'No';

  results.push({
    json: {
      messageId,
      subject,
      label,
      senderName: sender.name,
      senderEmail: sender.email,
      dateReceived,
      hasAttachments,
      attachmentCount: attachmentEntries.length,
      attachmentFilenames: attachmentEntries.map(a => a.fileName).join(', '),
      senderFolderName: sanitizeFolderName(sender.name),
      _attachmentKeys: attachmentEntries.map(a => a.key),
    },
    binary: item.binary,
    pairedItem: { item: i },
  });
}

// Nothing new to log/process this run
if (results.length === 0) {
  return [];
}

return results;

