// Turns each email into one item per attachment, all sharing the same
// destinationFolderId. This node's input comes from a merged registry
// item, so pairedItem back to the original email isn't reliable -
// match by messageId instead.
const results = [];
const mimeToExt = {
  'image/jpeg': '.jpg',
  'image/jpg': '.jpg',
  'image/png': '.png',
  'image/gif': '.gif',
  'image/webp': '.webp',
  'application/pdf': '.pdf',
  'text/plain': '.txt',
  'application/msword': '.doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '.docx',
  'application/vnd.ms-excel': '.xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '.xlsx',
  'application/vnd.ms-powerpoint': '.ppt',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': '.pptx'
};

const emailByMessageId = new Map();
for (const emailItem of $('Normalize and Filter New Emails').all()) {
  emailByMessageId.set(emailItem.json.messageId, emailItem);
}

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const folderItem = items[i];
  const source = emailByMessageId.get(folderItem.json.messageId);
  if (!source) continue;

  const json = source.json;
  const binary = source.binary || {};
  const keys = json._attachmentKeys || [];
  const destinationFolderId = folderItem.json.senderFolderId;

  for (const key of keys) {
    if (!binary[key]) continue;
    const binaryData = binary[key];
    let fileName = binaryData.fileName || key || 'file';
    const mimeType = binaryData.mimeType || 'application/octet-stream';
    if (!fileName.includes('.')) {
      const ext = mimeToExt[mimeType] || '';
      fileName = fileName + ext;
    }
    results.push({
      json: {
        messageId: json.messageId,
        label: json.label,
        dateReceived: json.dateReceived,
        senderFolderName: json.senderFolderName,
        filename: fileName,
        mimeType: mimeType,
        fileSize: binaryData.fileSize,
        destinationFolderId: destinationFolderId,
        originalKey: key
      },
      binary: {
        data: binaryData
      },
      pairedItem: { item: i },
    });
  }
}
return results;

