// Build a label -> date -> sender folder registry from existing Drive
// folders. Keys are normalized (trim + lowercase); if duplicate folders
// already exist, the first one found is kept.

const labelFolders = ($('Collect Label Folder List').first().json.labelFolders) || [];
const dateFolders = ($('Collect Date Folder List').first().json.dateFolders) || [];
const senderFolders = ($('Collect Sender Folder List').first().json.senderFolders) || [];

function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

const registry = {};

for (const f of labelFolders) {
  if (!f || !f.name || !f.id) continue;
  const key = norm(f.name);
  if (!registry[key]) {
    registry[key] = { id: f.id, name: String(f.name).trim(), dates: {} };
  }
}

const labelIdToKey = {};
for (const key of Object.keys(registry)) labelIdToKey[registry[key].id] = key;

for (const f of dateFolders) {
  if (!f || !f.name || !f.id) continue;
  const parents = f.parents || [];
  const parentLabelKey = parents.map(p => labelIdToKey[p]).find(Boolean);
  if (!parentLabelKey) continue;
  const dateKey = String(f.name).trim();
  const labelEntry = registry[parentLabelKey];
  if (!labelEntry.dates[dateKey]) {
    labelEntry.dates[dateKey] = { id: f.id, name: dateKey, senders: {} };
  }
}

const dateIdToLocation = {};
for (const labelKey of Object.keys(registry)) {
  for (const dateKey of Object.keys(registry[labelKey].dates)) {
    dateIdToLocation[registry[labelKey].dates[dateKey].id] = { labelKey, dateKey };
  }
}

for (const f of senderFolders) {
  if (!f || !f.name || !f.id) continue;
  const parents = f.parents || [];
  const loc = parents.map(p => dateIdToLocation[p]).find(Boolean);
  if (!loc) continue;
  const senderKey = norm(f.name);
  const dateEntry = registry[loc.labelKey].dates[loc.dateKey];
  if (!(senderKey in dateEntry.senders)) {
    dateEntry.senders[senderKey] = f.id;
  }
}

return [{ json: { registry } }];

// One item per label not already in the registry, deduped
const registry = $('Build Folder Registry').first().json.registry;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

const emails = $input.all();
const seen = new Set();
const missing = [];
for (const item of emails) {
  const label = item.json.label;
  const key = norm(label);
  if (!key || seen.has(key)) continue;
  seen.add(key);
  if (!registry[key]) {
    missing.push({ json: { labelKey: key, labelName: String(label).trim() } });
  }
}

// Nothing missing - emit a placeholder so downstream nodes still run
if (missing.length === 0) {
  return [{ json: { __kind: 'skip' } }];
}
return missing;

// Fold newly created label folders back into the registry in memory
const registry = JSON.parse(JSON.stringify($('Build Folder Registry').first().json.registry));
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

const created = $input.all();
for (const item of created) {
  const name = item.json.name;
  const id = item.json.id;
  if (!name || !id) continue;
  const key = norm(name);
  if (!registry[key]) {
    registry[key] = { id, name: String(name).trim(), dates: {} };
  }
}
return [{ json: { registry } }];

// Unique (label, date) pairs missing from the registry
const registry = $input.first().json.registry;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

const emails = $('Normalize and Filter New Emails').all().filter(i => i.json.hasAttachments === 'Yes');
const seen = new Set();
const missing = [];
for (const item of emails) {
  const labelKey = norm(item.json.label);
  const dateKey = String(item.json.dateReceived).trim();
  const targetKey = labelKey + '::' + dateKey;
  if (seen.has(targetKey)) continue;
  seen.add(targetKey);
  const labelEntry = registry[labelKey];
  if (!labelEntry) continue;
  if (!labelEntry.dates[dateKey]) {
    missing.push({ json: { labelKey, labelFolderId: labelEntry.id, dateKey } });
  }
}

// Nothing missing - emit a placeholder so downstream nodes still run
if (missing.length === 0) {
  return [{ json: { __kind: 'skip' } }];
}
return missing;

const registry = JSON.parse(JSON.stringify($('Merge Label Registry').first().json.registry));
const createdItems = $input.all();
const missingTargets = $('Determine Missing Date Folders').all();

for (let i = 0; i < createdItems.length; i++) {
  const created = createdItems[i].json;
  const target = missingTargets[i] ? missingTargets[i].json : null;
  if (!target || !created || !created.id) continue;
  const labelEntry = registry[target.labelKey];
  if (!labelEntry) continue;
  if (!labelEntry.dates[target.dateKey]) {
    labelEntry.dates[target.dateKey] = { id: created.id, name: target.dateKey, senders: {} };
  }
}
return [{ json: { registry } }];

// Unique (label, date, sender) triples missing from the registry
const registry = $input.first().json.registry;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

const emails = $('Normalize and Filter New Emails').all().filter(i => i.json.hasAttachments === 'Yes');
const seen = new Set();
const missing = [];
for (const item of emails) {
  const labelKey = norm(item.json.label);
  const dateKey = String(item.json.dateReceived).trim();
  const senderKey = norm(item.json.senderFolderName);
  const targetKey = labelKey + '::' + dateKey + '::' + senderKey;
  if (seen.has(targetKey)) continue;
  seen.add(targetKey);
  const labelEntry = registry[labelKey];
  const dateEntry = labelEntry && labelEntry.dates[dateKey];
  if (!dateEntry) continue;
  if (!(senderKey in dateEntry.senders)) {
    missing.push({ json: { labelKey, dateKey, dateFolderId: dateEntry.id, senderKey, senderFolderName: item.json.senderFolderName } });
  }
}

// Nothing missing - emit a placeholder so downstream nodes still run
if (missing.length === 0) {
  return [{ json: { __kind: 'skip' } }];
}
return missing;

const registry = JSON.parse(JSON.stringify($('Merge Date Registry').first().json.registry));
const createdItems = $input.all();
const missingTargets = $('Determine Missing Sender Folders').all();

for (let i = 0; i < createdItems.length; i++) {
  const created = createdItems[i].json;
  const target = missingTargets[i] ? missingTargets[i].json : null;
  if (!target || !created || !created.id) continue;
  const labelEntry = registry[target.labelKey];
  const dateEntry = labelEntry && labelEntry.dates[target.dateKey];
  if (!dateEntry) continue;
  if (!(target.senderKey in dateEntry.senders)) {
    dateEntry.senders[target.senderKey] = created.id;
  }
}
return [{ json: { registry } }];

// Attach the resolved sender folder id to each new email (once per
// email, not per attachment). Explode Attachments matches attachments
// back to these by messageId.
const registry = $input.first().json.registry;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }

const emails = $('Normalize and Filter New Emails').all();
const results = [];

for (let i = 0; i < emails.length; i++) {
  const item = emails[i];
  if (item.json.hasAttachments !== 'Yes') continue;

  const labelKey = norm(item.json.label);
  const dateKey = String(item.json.dateReceived).trim();
  const senderKey = norm(item.json.senderFolderName);

  const labelEntry = registry[labelKey];
  const dateEntry = labelEntry && labelEntry.dates[dateKey];
  const senderFolderId = dateEntry && dateEntry.senders[senderKey];

  if (!senderFolderId) {
    // Skip rather than guess if the folder wasn't resolved
    continue;
  }

  results.push({
    json: {
      messageId: item.json.messageId,
      label: item.json.label,
      dateReceived: item.json.dateReceived,
      senderFolderName: item.json.senderFolderName,
      senderFolderId,
    },
    // Input here is a single merged registry item, so pairedItem is always 0.
    // Downstream matching is done by messageId (see Explode Attachments).
    pairedItem: { item: 0 },
  });
}

return results;
